import numpy as np

def D(f, x, h=1e-5):
    """centrale differentie: benadert f'(x) met fout O(h^2)"""
    return (f(x + h) - f(x - h)) / (2 * h)

afgeleiden = [
    ('x^2',    lambda t: t**2,  lambda t: 2*t),      # machtregel
    ('x^3',    lambda t: t**3,  lambda t: 3*t**2),   # machtregel
    ('sin(x)', np.sin,          np.cos),             # vast
    ('exp(x)', np.exp,          np.exp),             # zichzelf
    ('ln(x)',  np.log,          lambda t: 1/t),      # vast
]
print(f"{'functie':10s} {'x':>5s} {'numeriek':>10s} {'regel':>10s}")
for naam, f, df in afgeleiden:
    for x in [0.5, 2.0]:
        print(f'{naam:10s} {x:5.1f} {D(f, x):10.4f} {df(x):10.4f}')
